steps.script:
var mk = GameState.get_unit("U_MORKANAUT_A")
var ab := []
for a in mk.meta.abilities:
	ab.append(str(a.get("name", "")) if a is Dictionary else str(a))
if "SUPER-HEAVY WALKER" in mk.meta.keywords:
	return "has the keyword (not the case under test)"
if not "Super-heavy Walker" in ab:
	return "no Super-heavy Walker ability"
return "ability only"

for c in tree.root.get_children():
	if c is Window and c != tree.root and str(c.name) == "DisembarkDialog":
		c.hide()
		c.queue_free()
return true

var md = PhaseManager.get_current_phase_instance().active_moves.get("U_MORKANAUT_A", {})
var staged: Array = md.get("staged_moves", [])
if staged.is_empty():
	return "not staged — " + tree.current_scene.movement_controller.illegal_reason_label.text
var d = staged[staged.size() - 1].get("dest")
var p := Vector2(float(d[0]), float(d[1])) if d is Array else Vector2(d.x, d.y)
if p.distance_to(Vector2(1260.0, 586.141732283465)) > 3.0:
	return "staged at %s" % str(p)
return "staged past the Gunwagon"

var mk = GameState.state.units["U_MORKANAUT_A"].models[0]
var gw = GameState.state.units["U_GUNWAGON_A"].models[0]
if Vector2(float(gw.position.x), float(gw.position.y)).distance_to(Vector2(1430.0, 586.141732283465)) > 0.5:
	return "the Gunwagon moved"
var p := Vector2(float(mk.position.x), float(mk.position.y))
if p.distance_to(Vector2(1260.0, 586.141732283465)) > 3.0:
	return "Morkanaut at %s" % str(p)
return "past the Gunwagon"
